import sys

def solve(x):
    if x == 0:
        return "-1"
    for a in range(1, 2**32):
        b = 2 * x - a
        if b > 0 and a ^ b == x:
            return f"{a} {b}"
    return "-1"

def main():
    import sys
    input = sys.stdin.read().split()
    t = int(input[0])
    results = []
    index = 1
    for _ in range(t):
        x = int(input[index])
        result = solve(x)
        results.append(result)
        index += 1
    print("\n".join(results))

if __name__ == "__main__":
    main()
